\begin{aligned}

& P(S_{t}=m \mid S_{t-1}=j)=P(S_{t}=m \mid S_{t-1}=j,Y_{1:t-1})\\

&P(S_{t}=m \mid Y_{1:t-1})= \sum_{j=1}^{M}P(S_{t-1}=j\mid Y_{1:t-1})P(S_{t}=m \mid S_{t-1}=j,Y_{1:t-1})\\

& \sum_{j=1}^{M}\alpha^{'}_{t-1}(j)P(S_{t}=m \mid S_{t-1} = j)

\end{aligned}
\end{equation}\]

